//! B1B590 byte listener-mask popcount, owned allocation and matrix transpose.
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory,audio_path_lifecycle::Runtime,audio_path_resource::Services};
fn word(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
pub fn initialize(node:&mut Memory,auxiliary:&mut Runtime,mask:u8,matrices:&[[u8;36];8],pool:u32,services:&mut impl Services)->Result<u32,Error>{
 if node.reference==0||node.raw.len()<108{return Err(Error::InvalidAllocation);}if word(&node.raw,104)!=0{return Ok(1);}
 let size=mask.count_ones()*36;let allocation=services.allocate(pool,size)?;let reference=allocation.as_ref().map_or(0,|m|m.reference);node.raw[104..108].copy_from_slice(&reference.to_le_bytes());let Some(memory)=allocation else{return Ok(2);};if reference==0||memory.raw.len()!=size as usize||auxiliary.auxiliary.contains_key(&reference){return Err(Error::InvalidAllocation);}auxiliary.auxiliary.insert(reference,memory);
 let mut offset=0;for lane in 0..8{if mask&(1<<lane)==0{continue;}for index in [0usize,3,6,1,4,7,2,5,8]{let bytes=&matrices[lane][index*4..index*4+4];if !f32::from_le_bytes(bytes.try_into().unwrap()).is_finite(){return Err(Error::Backend("nonfinite x87 listener matrix requires qualification"));}auxiliary.auxiliary.get_mut(&reference).unwrap().raw[offset..offset+4].copy_from_slice(bytes);offset+=4;}}
 Ok(1)
}
#[cfg(test)]mod tests{
 use super::*;use serde_json::{Value,json};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
 struct Backend{pattern:u8,failure:bool,buffer:Vec<u8>,calls:Vec<Value>}
 impl Services for Backend{fn allocate(&mut self,pool:u32,size:u32)->Result<Option<Memory>,Error>{let reference=if self.failure{0}else{0x40010000};self.calls.push(json!({"kind":"allocate","pool":pool,"bytes":size,"reference":reference}));if self.failure{return Ok(None);}self.buffer[..size as usize].fill(self.pattern);Ok(Some(Memory{reference,raw:self.buffer[..size as usize].to_vec()}))}fn free(&mut self,_:u32,_:&Memory)->Result<(),Error>{Err(Error::Backend("unexpected release during listener initialization"))}}
 #[test]fn audio_path_listener_orientation_matches2048_native_byte_masks_cached_oom_zero_allocation_and_transposed_matrices(){let p:Value=serde_json::from_str(include_str!("../../../data/4.20/audio_path_listener_orientation_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],2048);let matrices:[[u8;36];8]=p["listener_matrices"].as_array().unwrap().iter().map(|m|bytes(m.as_str().unwrap()).try_into().unwrap()).collect::<Vec<_>>().try_into().unwrap();for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let b=&row["before"];let mut node=Memory{reference:0x40004000,raw:bytes(b["node"].as_str().unwrap())};let mut auxiliary=Runtime::default();let mut backend=Backend{pattern:row["pattern"].as_u64().unwrap()as u8,failure:row["failure"].as_bool().unwrap(),buffer:bytes(b["buffer"].as_str().unwrap()),calls:vec![]};let result=initialize(&mut node,&mut auxiliary,row["mask"].as_u64().unwrap()as u8,&matrices,17,&mut backend).unwrap();assert_eq!(result,row["result"].as_u64().unwrap()as u32,"status {i}");assert_eq!(json!(backend.calls),row["calls"],"physical allocator {i}");let allocation=auxiliary.auxiliary.get(&0x40010000);if let Some(m)=allocation{backend.buffer[..m.raw.len()].copy_from_slice(&m.raw);}let allocated=allocation.map(|m|json!({"reference":m.reference,"size":m.raw.len(),"raw":hex(&m.raw)}));assert_eq!(json!({"node":hex(&node.raw),"buffer":hex(&backend.buffer),"allocated":allocated}),row["after"],"node/padding/allocation/matrix bytes {i}");}}
}
